import{_ as e,o as t,c as r,a5 as i}from"./chunks/framework.DJo0M80U.js";const P=JSON.parse('{"title":"整数与IP地址间的转换","description":"中等 通过率：36.75% 时间限制：1秒 空间限制：32M 知识点 字符串 模拟 描述 原理：ip地址的每段可以看成是一个0 255的整数，把每段拆分成一个二进制形式组合起来，然后把这个二进制数转变成 一个长整数。 举例：一个ip地址为10.0.3.193 每段数字 相对应的二。","frontmatter":{"title":"整数与IP地址间的转换","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"中等 通过率：36.75% 时间限制：1秒 空间限制：32M 知识点 字符串 模拟 描述 原理：ip地址的每段可以看成是一个0 255的整数，把每段拆分成一个二进制形式组合起来，然后把这个二进制数转变成 一个长整数。 举例：一个ip地址为10.0.3.193 每段数字 相对应的二。","sidebarWeight":111,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/特定算法/整数与IP地址间的转换.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/特定算法/整数与IP地址间的转换.md","filePath":"posts/前端面试与实战/03-算法训练/特定算法/整数与IP地址间的转换.md"}'),n={name:"posts/前端面试与实战/03-算法训练/特定算法/整数与IP地址间的转换.md"};function a(d,o,p,c,s,u){return t(),r("div",null,[...o[0]||(o[0]=[i('<div><h1 id="整数与ip地址间的转换" tabindex="-1">整数与IP地址间的转换 <a class="header-anchor" href="#整数与ip地址间的转换" aria-label="Permalink to &quot;整数与IP地址间的转换&quot;">​</a></h1><blockquote><p>本节目标：理解“整数与IP地址间的转换”的核心思路，并能把它用于实际开发或面试表达。 中等 通过率：36.75% 时间限制：1秒 空间限制：32M 知识点==字符串====模拟== <strong>描述</strong> 原理：ip地址的每段可以看成是一个0-255的整数，把每段拆分成一个二进制形式组合起来，然后把这个二进制数转变成 一个长整数。 举例：一个ip地址为10.0.3.193 每段数字 相对应的二进制数 10 00001010 0 00000000 3 00000011 193 11000001 组合起来即为：00001010 00000000 00000011 11000001,转换为10进制数就是：167773121，即该IP地址转换后的数字就是它了。 数据范围：保证输入的是合法的 IP 序列 <strong>输入描述：</strong> 输入 1 输入IP地址 2 输入10进制型的IP地址 <strong>输出描述：</strong> 输出 1 输出转换成10进制的IP地址 2 输出转换后的IP地址 <strong>示例1</strong> 输入： 10.0.3.193167969729 ==复制== 输出： 16777312110.3.3.193</p></blockquote><p>def ip_to_long(ip): &quot;&quot;&quot; 将点分十进制的IP地址转换为长整数 :param ip: 点分十进制的IP地址，如&#39;192.168.1.1&#39; :return: 对应的长整数 &quot;&quot;&quot; ip2num = 0 # 初始化IP长整数 for part in ip.split(&#39;.&#39;): # 分割IP地址为四个部分 ip2num = ip2num * 256 + int(part) # 每个部分转为整数，并累加到长整数 return ip2num</p><p>def long_to_ip(num): &quot;&quot;&quot; 将长整数转换回点分十进制的IP地址 :param num: IP地址对应的长整数 :return: 点分十进制的IP地址 &quot;&quot;&quot; num2ip = [] # 初始化存储每部分IP的列表 for i in range(3, -1, -1): # 从高位到低位处理每一部分</p><h1 id="通过整除256的幂得到每个部分的值-并将其转换为字符串添加到列表" tabindex="-1">通过整除256的幂得到每个部分的值，并将其转换为字符串添加到列表 <a class="header-anchor" href="#通过整除256的幂得到每个部分的值-并将其转换为字符串添加到列表" aria-label="Permalink to &quot;通过整除256的幂得到每个部分的值，并将其转换为字符串添加到列表&quot;">​</a></h1><p>num2ip.append(str(num // (256 ** i)))</p><h1 id="通过取模256的幂更新num-移除已处理的部分" tabindex="-1">通过取模256的幂更新num，移除已处理的部分 <a class="header-anchor" href="#通过取模256的幂更新num-移除已处理的部分" aria-label="Permalink to &quot;通过取模256的幂更新num，移除已处理的部分&quot;">​</a></h1><p>num = num % (256 ** i) return &#39;.&#39;.join(num2ip) # 将列表中的字符串用点连接成完整的IP地址</p><h1 id="读取输入-并处理异常" tabindex="-1">读取输入，并处理异常 <a class="header-anchor" href="#读取输入-并处理异常" aria-label="Permalink to &quot;读取输入，并处理异常&quot;">​</a></h1><p>while True: try: ip_input = input().strip() # 删除可能的首尾空白字符 num_input = input().strip()</p><h1 id="转换并打印ip地址到长整数的结果" tabindex="-1">转换并打印IP地址到长整数的结果 <a class="header-anchor" href="#转换并打印ip地址到长整数的结果" aria-label="Permalink to &quot;转换并打印IP地址到长整数的结果&quot;">​</a></h1><p>print(ip_to_long(ip_input))</p><h1 id="转换并打印长整数到ip地址的结果" tabindex="-1">转换并打印长整数到IP地址的结果 <a class="header-anchor" href="#转换并打印长整数到ip地址的结果" aria-label="Permalink to &quot;转换并打印长整数到IP地址的结果&quot;">​</a></h1><p>print( long_to_ip(int(num_input))) except EOFError: # 使用EOFError来捕捉输入结束的情况 break except ValueError: # 捕捉输入值异常</p><p><strong>ip2num</strong> <strong>=</strong> <strong>ip2num</strong> ***** <strong>256</strong> <strong>+</strong> <strong>int</strong>**(<strong><strong>part</strong></strong>)** 一个IP地址由四个数字组成，每个数字称为一个“段”。每个段的取值范围是0到255，即一个八位的二进制数。例如，IP地址<code>192.168.1.1</code>可以分成四个段：<code>192</code>，<code>168</code>，<code>1</code>，<code>1</code>。</p><p>在计算机中，这些数字会转换成二进制形式。让我们来看<code>192.168.1.1</code>这个地址各个段的二进制形式是什么：</p><ul><li><code>192</code> -&gt; <code>11000000</code></li><li><code>168</code> -&gt; <code>10101000</code></li><li><code>1</code> -&gt; <code>00000001</code></li><li><code>1</code> -&gt; <code>00000001</code></li></ul><p>每个段转换为二进制后都是8位，因为最大值255用二进制表示正好是<code>11111111</code>，即8个1。</p><p>现在，我们要将这四个二进制数拼接起来，形成一个长二进制数。拼接的结果就是这个IP地址的二进制表示。按照上面的例子，拼接后的结果是：</p><p><code>11000000 10101000 00000001 00000001</code></p><p>这是一个32位的二进制数，因为每个段是8位，总共有4个段。</p><p>现在我们来到了你提到的那行代码。由于我们处理的是十进制数，而不是二进制数，我们需要一种方法来模拟这种“拼接”操作。这就是<code>* 256</code>（即<code>2^8</code>，因为一个段有8位）和<code>+ int(part)</code>的作用。</p><ul><li>首先，我们取第一个段的值，比如<code>192</code>，我们还没有其他段要处理，所以现在的数就是<code>192</code>。</li><li>然后我们要加上第二个段的值。在加之前，我们先将目前的数（<code>192</code>）乘以<code>256</code>。这相当于在二进制中将<code>11000000</code>向左移动8位（因为乘以<code>2</code>就是向左移动一位）。所以<code>192 * 256</code>（或者二进制中的<code>11000000</code>向左移动8位）给了我们<code>11000000 00000000</code>。然后我们加上下一个段的值，比如<code>168</code>，得到<code>11000000 10101000</code>。</li><li>我们对后面的段重复这个过程，每次都先乘以<code>256</code>，然后加上下一个段的值。</li></ul><p>通过这种方式，我们模拟了将四个八位二进制数拼接起来的过程，只不过我们使用的是十进制的数学操作。</p></div>',1)])])}const _=e(n,[["render",a]]);export{P as __pageData,_ as default};
